// Generates the exhaustive bf16 -> FP8 E4M3 / FP4 E2M1 conversion table used by
// crates/sparkflash-kernels/tests/m4_codec_golden.rs. Compiled and run by nvcc 12.9.1; the host
// has no GPU, and none is needed: these converters are host-callable.
#include <cstdio>
#include <cstdint>
#include <cuda_bf16.h>
#include <cuda_fp8.h>
#include <cuda_fp4.h>

// The output path is an argument rather than a hardcoded one, so this generator can be run
// anywhere - a CI job or a container with the repo bind-mounted - and compared against the
// committed fixture. scripts/regen-codec-fixture.sh is the in-tree way to do that.
int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <output.hex>\n", argv[0]);
        return 2;
    }
    // Index = bf16 bit pattern, 0..65535. The kernels only ever encode values that arrived as
    // bf16 (residual stream, activations), so this is the complete input domain of the encoders.
    FILE *out = fopen(argv[1], "w");
    if (out == nullptr) {
        fprintf(stderr, "cannot write %s\n", argv[1]);
        return 1;
    }
    fprintf(out, "# generated by nvcc 12.9.86 (CUDA 12.9.1, nvidia/cuda:12.9.1-devel-ubuntu22.04)\n");
    fprintf(out, "# index = bf16 bit pattern 0..65535; x = (float)__bfloat162float(bits)\n");
    fprintf(out, "# fp8[index] = __nv_cvt_float_to_fp8(x, __NV_SATFINITE, __NV_E4M3)\n");
    fprintf(out, "# fp4[index] = __nv_cvt_float_to_fp4(x, __NV_E2M1, cudaRoundNearest)\n");
    for (uint32_t bits = 0; bits < 65536u; ++bits) {
        const __nv_bfloat16 value = __ushort_as_bfloat16((unsigned short)bits);
        const float x = __bfloat162float(value);
        const unsigned char fp8 = (unsigned char)__nv_cvt_float_to_fp8(x, __NV_SATFINITE, __NV_E4M3);
        const unsigned char fp4 = (unsigned char)__nv_cvt_float_to_fp4(x, __NV_E2M1, cudaRoundNearest);
        fprintf(out, "%02x%01x", (unsigned)fp8, (unsigned)(fp4 & 0x0fu));
    }
    fprintf(out, "\n");
    fclose(out);
    return 0;
}
